        CategoryIconOption(key: "archive", label: "Archive", group: "Other", systemImage: "archivebox.fill"),
        CategoryIconOption(key: "send", label: "Send", group: "Other", systemImage: "paperplane.fill"),
        CategoryIconOption(key: "download", label: "Download", group: "Other", systemImage: "arrow.down"),
        CategoryIconOption(key: "upload", label: "Upload", group: "Other", systemImage: "arrow.up"),
        CategoryIconOption(key: "search", label: "Search", group: "Other", systemImage: "magnifyingglass"),
        CategoryIconOption(key: "filter", label: "Filter", group: "Other", systemImage: "line.3.horizontal.decrease"),
        CategoryIconOption(key: "sliders-horizontal", label: "Sliders", group: "Other", systemImage: "slider.horizontal.3"),
        CategoryIconOption(key: "circle", label: "Circle", group: "Other", systemImage: "circle.fill"),
        CategoryIconOption(key: "square", label: "Square", group: "Other", systemImage: "square.fill"),
        CategoryIconOption(key: "triangle", label: "Triangle", group: "Other", systemImage: "triangle.fill"),
        CategoryIconOption(key: "hexagon", label: "Hexagon", group: "Other", systemImage: "hexagon.fill"),
        CategoryIconOption(key: "diamond", label: "Diamond", group: "Other", systemImage: "diamond.fill")
    ]

    static var grouped: [(group: String, icons: [CategoryIconOption])] {
        groups.compactMap { group in
            let icons = all.filter { $0.group == group }
            guard !icons.isEmpty else { return nil }
            return (group: group, icons: icons)
        }
    }

    static func systemImage(forKey key: String?) -> String? {
        guard let key else { return nil }
        return all.first(where: { $0.key == key })?.systemImage
    }

    static func option(forKey key: String?) -> CategoryIconOption? {
        guard let key else { return nil }
        return all.first(where: { $0.key == key })
    }
}
